mapper.sql:
AND (#{unrestricted}=TRUE

    OR t.dept_id IN #{dept}

OR t.publisher_user_id=#{selfUserId})

mapper.select:
SELECT , d.dept_name AS deptName,
  (SELECT COUNT(*) FROM ca_inventory_item i WHERE i.task_id=t.task_id) AS totalCount,
  (SELECT COUNT(*) FROM ca_inventory_item i WHERE i.task_id=t.task_id AND i.checked_time IS NOT NULL) AS checkedCount,
  (SELECT COUNT(*) FROM ca_inventory_item i WHERE i.task_id=t.task_id AND i.review_status='1') AS reviewedCount
FROM ca_inventory_task t LEFT JOIN sys_dept d ON d.dept_id=t.dept_id
WHERE 1=1 

    AND (t.task_no LIKE CONCAT('%',#{keyword},'%') OR t.task_name LIKE CONCAT('%',#{keyword},'%'))

AND t.status=#{status}
AND t.dept_id=#{deptId}
AND t.start_time >= #{beginTime}
AND t.end_time <= #{endTime}
ORDER BY t.task_id DESC

SELECT ,a.asset_code AS assetCode,a.asset_name AS assetName, u.nick_name AS assignedUserName FROM ca_inventory_item i JOIN ca_inventory_task t ON t.task_id=i.task_id JOIN ca_asset a ON a.asset_id=i.asset_id LEFT JOIN sys_user u ON u.user_id=i.assigned_user_id WHERE 1=1 AND i.task_id=#{taskId} AND i.review_status=#{reviewStatus} AND i.checked_time IS NULL AND i.checked_time IS NOT NULL AND i.missing_flag='1' AND i.checked_time IS NOT NULL AND i.observed_condition='1' AND i.checked_time IS NOT NULL AND i.observed_location_id != CAST(JSON_UNQUOTE(JSON_EXTRACT(i.base_snapshot,'$.location_id')) AS UNSIGNED) AND t.status=#{status} AND t.dept_id=#{deptId}
AND (a.asset_code LIKE CONCAT('%',#{keyword},'%') OR a.asset_name LIKE CONCAT('%',#{keyword},'%'))
ORDER BY i.task_id DESC,i.item_id
